# -*- coding: utf-8 -*-
import sys,json,hashlib
from pathlib import Path
root=Path(__file__).resolve().parent.parent
out=root/'output/acceptance'
results=json.loads((out/'acceptance_results.json').read_text(encoding='utf-8-sig'))
assert len(results)==5 and not any(x['status']=='FAIL' for x in results)
assert all(x['source_unchanged'] for x in results)
boundary=json.loads((out/'boundary_results.json').read_text(encoding='utf-8-sig'))
recovery=json.loads((out/'recovery_results.json').read_text(encoding='utf-8-sig'))
assert all(recovery.values())
exe=root/'AI-Music-Processor.exe'
lines=['# 一体化音乐处理验收报告','','日期：2026-10-04。环境：本机 Windows、GTX 1060 6GB、Torch 2.0.0+cu118、RVC 0618 Python 3.9.13，FP32。代码和原文档备份：temp/baseline_20261004。','','## 结论','','自动音频主链路已实际贯通，已有完整歌曲的分轨、清理、换声、MIDI、对齐、混音、母带和 WAV/MP3/FLAC。测试没有覆盖“完美音质”或全部原设计扩展；MuseScore/LMMS 实际导入超时仍未闭环。因此不能将本次交付写为原设计116章全部验收通过。','','## 真实输入与真实模型','','| 案例 | 结果 | 秒 | LUFS | True Peak dBTP | 局部同步最大 ms |','|---|---|---:|---:|---:|---:|']
for x in results+boundary:
    qc=x['manifest']['qc'];a=qc.get('alignment') or {}
    lines.append(f"| {x['name']} | {x['status']} | {x['elapsed']:.2f} | {qc['integrated_lufs']:.2f} | {qc['true_peak_dbtp']:.2f} | {a.get('max_local_residual_ms','N/A')} |")
lines+=['','所有案例检查输入 SHA-256 不变。MP3/M4A/WAV/OGG/Opus/FLAC 输入包含单声道、立体声、中文及长文件名。完整歌曲约289.8秒；分离/换声没有用模拟成功产物。WAV 使用24-bit/44.1k或48k，MP3 320k；每种导出均完整解码并单独检测峰值。','','短换声分别调用周杰伦、赵露思，整曲调用孙燕姿+7半音。四轨为本地HTDemucs，MIDI为Basic Pitch ONNX。自动MIDI对象是主唱；贝斯/鼓及完整配器不是已验证自动扒谱功能。','','### 成品项目']
for x in results:
    m=x['manifest'];project=Path(m['output_paths']['reports_dir']).parent
    lines.append(f"- {x['name']}：[{project.name}](../{project.relative_to(root).as_posix()}/project.json)")
lines+=['','','## 确定问题与修复','','- 去掉分析失败时虚构的默认响度/元信息；坏文件、静音、缺失导出会失败。','- 修正correlation偏移方向、Limiter延迟补偿、全局对齐后重新测量残余；补上可信局部平滑时间修正。局部变速限制0.5%，仅在相同窗口覆盖且最大残差下降时接受。','- 分离与RVC互斥、独立Worker、长音频原生分段；当前版本明确不使用不存在的RMVPE。','- 补上SQLite Job/Stage、源与产物哈希、恢复、跨项目缓存重定位和缓存命中的输出登记。','- QC静音人声门禁防止伴奏掩盖换声失败；数值失败不会标记完成。','- 每项导出检测True Peak并有界衰减修复；四轨伴奏重新求和，不将人声混回伴奏。','- 队列参数持久化、唯一dispatch_id、同秒同名项目UUID、Tk主线程事件队列、失败日志。','','## 工程验证','','- 11项自动回归通过：双向偏移、局部漂移、坏文件、静音、缺失导出、静音人声、24bit/44.1k与MP3/FLAC、取消进程、SQLite/哈希/授权。日志：[final_tests.log](../logs/final_tests.log)。','- 6项故障恢复通过：失败状态持久化、有效阶段跳过、缺失母带重建、损坏缓存重解码、源文件保护、源变化拒绝恢复。证据：[recovery_results.json](../output/acceptance/recovery_results.json)。','- C# EXE实际启动Pythonw及Tk构造烟测通过，检测到三模型；[launcher_smoke.json](../temp/launcher_smoke.json)。这不是人工完整界面交互或干净设备验收。','- 独立reviewer两轮审查SHIP，无P0/P1阻断；末轮窗口覆盖/变速限制与失败日志保护建议已修，相关回归通过。','- core与桌面入口py_compile通过。','','EXE SHA-256：`'+hashlib.sha256(exe.read_bytes()).hexdigest()+'`。EXE是启动器，须保留完整tools/runtime目录，不是全依赖独立安装包。','','## 尚未闭环','','1. 四轨伴奏样例响度偏离请求目标，QC保留WARN；峰值预算放宽和衰减过程见master旁车JSON。不能直接认定为适合所有歌曲的最佳母带。','2. MuseScore MIDI→MusicXML与LMMS MIDI --import多次超时（MuseScore45/60秒，LMMS30秒，含隔离配置与offscreen尝试）。命令已接上真实产物，现有TimGM6mb.sf2已给LMMS配置，仍未证明编辑器内实际导入、回放、排版。未改动全局编辑器配置或终止用户进程。','3. 未做完整人工A/B试听、音色相似度、歌词发音、MIDI准确率、其他Windows设备验收。自动PASS仅表示当前数值/文件门禁通过。','4. 原设计所有未实现项逐章列在[需求落地矩阵](需求落地矩阵.md)。尤其Pitch Correction、DeepFilterNet、自动OOM降级、缓存TTL/容量回收、波形与通知等仍未实施。','','## 可复核证据与命令','','- [acceptance_results.json](../output/acceptance/acceptance_results.json)：每案例参数、模型、输出、QC和Stage。','- [boundary_results.json](../output/acceptance/boundary_results.json)：30秒/长中文名/OGG/Opus/FLAC追加验收。','- [diagnostics.json](../output/acceptance/diagnostics.json)：已配置组件；编辑器仅有PE文件不能算PASS。','- [final_acceptance.log](../logs/final_acceptance.log)、[worker.jsonl](../logs/worker.jsonl)：实际子进程及结果。','','```powershell',"& 'tools/RVC/RVC-beta-v2-0618/runtime/python.exe' tests/run_acceptance.py","& 'tools/RVC/RVC-beta-v2-0618/runtime/python.exe' tests/run_boundary_acceptance.py","& 'tools/RVC/RVC-beta-v2-0618/runtime/python.exe' tests/run_recovery.py",'```','','复跑真实引擎会重新计算并产生新项目，耗时依模型与缓存而异。','','## 技术依据','','- [LMMS 1.2.2实际命令行参数](https://github.com/LMMS/lmms/blob/v1.2.2/src/core/main.cpp)：MIDI使用--import，配置使用--config。','- [Basic Pitch官方实现](https://github.com/spotify/basic-pitch)：当前采用本地ONNX模型。','- [Demucs官方实现](https://github.com/facebookresearch/demucs)：当前采用本地HTDemucs模型。']
lines+=['','## 收尾追加验收','','- [gui_queue_results.json](../output/acceptance/gui_queue_results.json)：桌面真实队列连续处理两首歌均为PASS；处理中修改模式和半音，已派发任务仍保留原精修参数及唯一dispatch_id。测试使用独立配置目录，没有覆盖现有设置。','- [post_audit_results.json](../output/acceptance/post_audit_results.json)：最终代码重新对齐整曲，人声音轨与已交付对齐文件最大逐样本差为0；按最新10ms同步目标重新QC仍为PASS，局部残余1.5ms。','- 合计9个音频案例：8个PASS、1个响度WARN；另有2首真实桌面队列、11项回归、6项恢复检查及EXE启动烟测。']
lines.extend('\n## 2026-10-04 拖拽闪退修复\n\n用户报告“一拖就闪退”后，用实际 WM_DROPFILES 异步消息复现了 Python/Tk 原生崩溃：`PyEval_RestoreThread ... current Python thread state is NULL`。之前只验证添加文件及队列，没有覆盖这个异步原生入口，属于验收漏项。\n\n根因：Windows WndProc 回调直接调用 `window.after()`，绕过了 Tk 的 Tcl/Python 线程桥接。修复为原生回调仅写入 Python 事件队列，由 Tk 主线程定时处理路径；窗口销毁前恢复原 WndProc。\n\n旧版首个异步消息稳定崩溃，新版连续20次异步消息通过，包含64位句柄、中文/空格路径、多文件、文件夹及重复过滤。有效音频进入等待队列，不自动开始处理；待添加完成后点击开始。证据：[drop_results.json](../output/acceptance/drop_results.json)、[修复后日志](../logs/drop_acceptance.log)、[旧版崩溃日志](../logs/drop_baseline_crash.log)。测试脚本：tests/run_drop_acceptance.py。原代码备份：temp/drag_baseline_20261004.pyw。\n'.splitlines())
(root/'docs/验收报告.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
